#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "var".parse::<ElectricReactivePowerUnit>(),
        Ok(ElectricReactivePowerUnit::VoltampereReactive)
    );
    assert_eq!(
        format!("2.5 {}", "var").parse::<ElectricReactivePower>(),
        Ok(ElectricReactivePower::new(
            2.5,
            ElectricReactivePowerUnit::VoltampereReactive
        ))
    );
    assert_eq!(
        "kvar".parse::<ElectricReactivePowerUnit>(),
        Ok(ElectricReactivePowerUnit::KilovoltampereReactive)
    );
    assert_eq!(
        format!("2.5 {}", "kvar").parse::<ElectricReactivePower>(),
        Ok(ElectricReactivePower::new(
            2.5,
            ElectricReactivePowerUnit::KilovoltampereReactive
        ))
    );
    assert_eq!(
        "Mvar".parse::<ElectricReactivePowerUnit>(),
        Ok(ElectricReactivePowerUnit::MegavoltampereReactive)
    );
    assert_eq!(
        format!("2.5 {}", "Mvar").parse::<ElectricReactivePower>(),
        Ok(ElectricReactivePower::new(
            2.5,
            ElectricReactivePowerUnit::MegavoltampereReactive
        ))
    );
    assert_eq!(
        "Gvar".parse::<ElectricReactivePowerUnit>(),
        Ok(ElectricReactivePowerUnit::GigavoltampereReactive)
    );
    assert_eq!(
        format!("2.5 {}", "Gvar").parse::<ElectricReactivePower>(),
        Ok(ElectricReactivePower::new(
            2.5,
            ElectricReactivePowerUnit::GigavoltampereReactive
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricReactivePower>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricReactivePower::from_base(6.0);
    let b = ElectricReactivePower::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricReactivePower::<i64>::from_base(7);
    let b = ElectricReactivePower::<i64>::from_base(2);
    assert_eq!(a + b, ElectricReactivePower::from_base(9));
    assert_eq!(a % b, ElectricReactivePower::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricReactivePower<i64>>(),
        ElectricReactivePower::from_base(9)
    );
}
